mapper.update:
update srm_po
   set status = #{to}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where po_id = #{poId} and status = #{from}

mapper.select:
select p.po_id, p.po_no, p.rev, p.status, c.cust_cd, p.po_date
  from srm_po p join mst_cust c on c.cust_id = p.cust_id
 where p.po_no = #{poNo}

mapper.sql:
select * from ( select l.po_line_id, p.po_id, p.po_no, p.rev, p.po_date, c.cust_cd, c.cust_nm, p.status, l.line_no, i.item_cd, l.item_nm, l.unit_cd, trim_scale(l.qty - l.cancel_qty - l.recv_qty)::text as open_qty, trim_scale(l.recv_qty)::text as recv_qty, l.due_date, va.ack_status, (p.issued_at at time zone #{c.zone})::date + #{c.dueDays} as ack_due_date, trim_scale(pr.qty)::text as promised_qty, pr.first_date as promised_first, pr.last_date as promised_last, ((va.ack_id is null or va.ack_status = 'REJECTED') and #{c.today} > (p.issued_at at time zone #{c.zone})::date + #{c.dueDays}) as overdue, pr.last_date - l.due_date as late_days, l.due_date - #{c.today}::date as due_in_days from srm_po p join mst_cust c on c.cust_id = p.cust_id join srm_po_line l on l.po_id = p.po_id and l.line_status = 'OPEN' and l.qty - l.cancel_qty - l.recv_qty > 0 join mst_item i on i.item_id = l.item_id
left join lateral (select sum(al.promised_qty) as qty, min(al.promised_date) as first_date, max(al.promised_date) as last_date from srm_po_ack_line al where al.ack_id = va.ack_id and al.po_line_id = l.po_line_id) pr on true where p.po_date between #{c.from} and #{c.to} and p.status in ('ISSUED', 'ACKED', 'PARTIAL_RECEIVED') and c.cust_cd = #{c.custCd}
and (p.po_no ilike #{c.keywordLike} escape '\' or c.cust_nm ilike #{c.keywordLike} escape '\' or i.item_cd ilike #{c.keywordLike} escape '\' or l.item_nm ilike #{c.keywordLike} escape '\')
) x
where x.overdue where x.late_days > 0 where x.due_in_days <= #{c.soonDays}
